function primeBuzzer(){if(!buzzerReady&&ctx)buzzerReady=fetch(horn.src).then(r=>{if(!r.ok)throw Error('Buzzer unavailable');return r.arrayBuffer()}).then(data=>ctx.decodeAudioData(data)).then(buffer=>{buzzerBuffer=buffer}).catch(()=>{buzzerReady=null})}
