let stopClockAdjustment=()=>{};
function bindHeldAdjustment(button,change){
  let delay,repeat,held=false,pointerId;
  const adjust=()=>{if(button.disabled){stop();return}change();if(button.disabled)stop()};
  const stop=()=>{clearTimeout(delay);clearInterval(repeat);held=false;pointerId=undefined};
  const start=()=>{stopClockAdjustment();stopClockAdjustment=stop;held=true;adjust();if(!held)return;delay=setTimeout(()=>{if(!held)return;adjust();if(held)repeat=setInterval(adjust,100)},400)};
  button.onpointerdown=e=>{if(e.isPrimary===false||e.button!==0||held)return;e.preventDefault();start();pointerId=e.pointerId;try{button.setPointerCapture(e.pointerId)}catch{}};
  button.onpointerup=button.onpointercancel=e=>{if(e.pointerId===pointerId)stop()};
  button.onlostpointercapture=button.onpointerleave=stop;
  button.onclick=(e={detail:0})=>{if(e.detail===0&&!held)adjust()};
  button.onkeydown=e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();if(!held&&!e.repeat)start()}};
  button.onkeyup=e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();stop()}};
  button.onblur=stop;
  button.oncontextmenu=e=>e.preventDefault();
}
